(function(root){'use strict';
const assets=['bitcoin','gold','dxy'];
function mean(x){return x.length?x.reduce((s,v)=>s+v,0)/x.length:null;}
function sd(x){if(x.length<2)return null;const m=mean(x);return Math.sqrt(x.reduce((s,v)=>s+(v-m)**2,0)/(x.length-1));}
function corr(x,y){if(x.length!==y.length||x.length<2)return null;const mx=mean(x),my=mean(y);let a=0,b=0,c=0;for(let i=0;i<x.length;i++){const dx=x[i]-mx,dy=y[i]-my;a+=dx*dy;b+=dx*dx;c+=dy*dy;}return b>0&&c>0?Math.max(-1,Math.min(1,a/Math.sqrt(b*c))):null;}
function quantile(x,p){if(!x.length)return null;const a=[...x].sort((x,y)=>x-y),i=(a.length-1)*p,f=Math.floor(i);return a[f]+(a[Math.ceil(i)]-a[f])*(i-f);}
function parseCSV(text){text=String(text).replace(/^\uFEFF/,'');let out=[],r=[],s='',q=false,closed=false;for(let i=0;i<text.length;i++){const c=text[i];if(q){if(c==='"'){if(text[i+1]==='"'){s+='"';i++;}else{q=false;closed=true;}}else s+=c;}else if(c==='"'){if(s||closed)throw Error('Unexpected quote.');q=true;}else if(c===','){r.push(s);s='';closed=false;}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;r.push(s);if(r.some(v=>v.trim()))out.push(r);r=[];s='';closed=false;}else{if(closed&&!/\s/.test(c))throw Error('Unexpected characters after a quoted field.');if(!closed)s+=c;}}if(q)throw Error('Unclosed quote.');r.push(s);if(r.some(v=>v.trim()))out.push(r);if(out.length<3)throw Error('Include a header and at least two complete price observations.');const h=out.shift().map(v=>v.trim().toLowerCase());if(h.some(v=>!v)||new Set(h).size!==h.length)throw Error('Headers must be unique and non-empty.');for(const k of ['date',...assets])if(!h.includes(k))throw Error('Missing column: '+k);if(out.length>20000)throw Error('Maximum 20,000 data records.');const mapped=out.map((r,i)=>{if(r.length!==h.length)throw Error('Record '+(i+2)+' has an incorrect field count.');return Object.fromEntries(h.map((k,j)=>[k,r[j].trim()]));});return clean(mapped);}
function clean(raw){if(!Array.isArray(raw))throw Error('Expected price rows.');const seen=new Set();let dropped=0;const rows=[];for(const [i,r] of raw.entries()){const date=String(r.date??'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)throw Error('Invalid ISO date in record '+(i+2));if(seen.has(date))throw Error('Duplicate date: '+date);seen.add(date);if(assets.some(k=>r[k]===null||r[k]===undefined||String(r[k]).trim()==='')){dropped++;continue;}const p={date};for(const k of assets){const n=Number(r[k]);if(!Number.isFinite(n)||n<=0)throw Error('Record '+(i+2)+': '+k+' must be a positive finite price.');p[k]=n;}rows.push(p);}rows.sort((a,b)=>a.date.localeCompare(b.date));if(rows.length<2)throw Error('At least two complete price observations are required.');return {rows,quality:{inputRows:raw.length,retainedRows:rows.length,droppedRows:dropped,policy:'Complete observed dates only. No forward-fill or interpolation.'}};}
function analyze(prices,window=90){if(!Number.isInteger(window)||window<2)throw Error('Window must be at least 2 observations.');if(prices.length<2)throw Error('Choose a range with at least two price observations.');const returns=prices.slice(1).map((r,i)=>Object.fromEntries([['date',r.date],...assets.map(k=>[k,Math.log(r[k])-Math.log(prices[i][k])])]));const stats={},drawdowns=prices.map(r=>({date:r.date}));for(const k of assets){let peak=prices[0][k],maxDD=0;for(let i=0;i<prices.length;i++){peak=Math.max(peak,prices[i][k]);const dd=prices[i][k]/peak-1;drawdowns[i][k]=dd;maxDD=Math.min(maxDD,dd);}const v=returns.map(r=>r[k]);stats[k]={totalReturn:prices.at(-1)[k]/prices[0][k]-1,meanLogReturn:mean(v),intervalVolatility:sd(v),maxDrawdown:maxDD,negativeShare:v.filter(x=>x<0).length/v.length};}
 for(const k of assets)if(!Number.isFinite(stats[k].totalReturn))throw Error('Price ratios exceed the supported numeric range.');
 const matrix=Object.fromEntries(assets.map(a=>[a,Object.fromEntries(assets.map(b=>[b,corr(returns.map(r=>r[a]),returns.map(r=>r[b]))]))]));const rolling=[];for(let i=window-1;i<returns.length;i++){const slice=returns.slice(i-window+1,i+1);rolling.push({date:returns[i].date,bitcoin_gold:corr(slice.map(r=>r.bitcoin),slice.map(r=>r.gold)),bitcoin_dxy:corr(slice.map(r=>r.bitcoin),slice.map(r=>r.dxy)),gold_dxy:corr(slice.map(r=>r.gold),slice.map(r=>r.dxy))});}
 const maxGap=Math.max(...returns.map((r,i)=>(Date.parse(r.date)-Date.parse(prices[i].date))/86400000));return {prices,returns,stats,matrix,rolling,drawdowns,window,maxGap};}
function stress(returns,tail=.1){if(!(tail>0&&tail<1))throw Error('Invalid tail fraction.');const threshold=quantile(returns.map(r=>r.dxy),1-tail);const selected=returns.filter(r=>r.dxy>0&&r.dxy>=threshold);const summarize=data=>Object.fromEntries(assets.map(k=>[k,{meanLogReturn:mean(data.map(r=>r[k])),negativeShare:data.length?data.filter(r=>r[k]<0).length/data.length:null,corrDXY:corr(data.map(r=>r[k]),data.map(r=>r.dxy))}]));return {threshold,selected,baseline:summarize(returns),conditional:summarize(selected),n:selected.length};}
function csv(rows){return rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');}
const api={assets,mean,sd,corr,quantile,parseCSV,clean,analyze,stress,csv};if(typeof module!=='undefined')module.exports=api;else root.Explorer=api;
})(typeof window==='undefined'?globalThis:window);
